def _can_do_colour(no_color: bool = None, force_color: bool = None) -> bool:
    """Check env vars and for tty/dumb terminal

    Args:
        no_color: If True, disable color regardless of other settings
        force_color: If True and no_color is not True, force color regardless of other settings
    """
    # 1. Parameter no_color takes highest precedence
    if no_color:
        return False

    # 2. Parameter force_color takes second precedence
    if force_color:
        return True

    # 3. Environment variable ANSI_COLORS_DISABLED
    if "ANSI_COLORS_DISABLED" in os.environ:
        return False

    # 4. Environment variable NO_COLOR
    if "NO_COLOR" in os.environ:
        return False

    # 5. Environment variable FORCE_COLOR
    if "FORCE_COLOR" in os.environ:
        return True

    # 6. Check for dumb terminal
    if os.environ.get("TERM") == "dumb":
        return False

    # 7. Terminal detection
    if not hasattr(sys.stdout, "fileno"):
        return False
    try:
        return os.isatty(sys.stdout.fileno())
    except io.UnsupportedOperation:
        return sys.stdout.isatty()
